"use client";
import { useMemo, useState } from "react";
import { useFormState, useFormStatus } from "react-dom";
import { sendQuote, type SendQuoteState } from "./actions";
import { Button, Card, Field, Input, Textarea, Select, FormError } from "@/components/ui";
import { categoryLabel } from "@/lib/constants";
import { money } from "@/lib/format";
function Submit(){const {pending}=useFormStatus();return <Button type="submit" size="lg" className="w-full sm:w-auto" disabled={pending}>{pending?"Sending…":"Send quote"}</Button>}
export function QuoteForm({conversationId,categories}:{conversationId:string;categories:string[]}){
 const action=sendQuote.bind(null,conversationId); const [state,formAction]=useFormState<SendQuoteState,FormData>(action,{}); const [rows,setRows]=useState([{label:"",amount:""},{label:"",amount:""}]); const subtotal=useMemo(()=>rows.reduce((s,r)=>s+(Number(r.amount)||0),0),[rows]);
 return <form action={formAction}><Card variant="feature" padding="lg" className="space-y-6"><Field label="Service category"><Select name="category" defaultValue={categories[0]??""}>{!categories.length&&<option value="">—</option>}{categories.map(c=><option key={c} value={c}>{categoryLabel(c)}</option>)}</Select></Field><div><div className="mb-3 flex items-end justify-between"><div><p className="text-sm font-semibold text-ink-900">Quote items</p><p className="mt-1 text-xs text-ink-500">Break pricing down so your client knows exactly what’s included.</p></div></div><div className="space-y-2">{rows.map((r,i)=><div key={i} className="grid grid-cols-12 gap-2"><Input name={`label_${i}`} placeholder="e.g. Organic balloon installation" className="col-span-8" value={r.label} onChange={e=>setRows(rs=>rs.map((x,j)=>j===i?{...x,label:e.target.value}:x))}/><Input name={`amount_${i}`} type="number" min={0} placeholder="$" className="col-span-4" value={r.amount} onChange={e=>setRows(rs=>rs.map((x,j)=>j===i?{...x,amount:e.target.value}:x))}/></div>)}{rows.length<8&&<button type="button" onClick={()=>setRows(rs=>[...rs,{label:"",amount:""}])} className="mt-2 text-sm font-semibold text-plum-700 hover:underline">+ Add another item</button>}</div></div><div className="rounded-2xl bg-ivory-100 p-4"><div className="flex items-center justify-between"><span className="text-sm font-medium text-ink-600">Quote subtotal</span><span className="font-display text-3xl text-ink-900">{money(subtotal)}</span></div></div><div className="grid gap-4 sm:grid-cols-2"><Field label="Deposit to book" hint="Defaults to 30% if left blank"><Input name="deposit" type="number" min={0} placeholder={String(Math.round(subtotal*.3))}/></Field><Field label="Quote valid until"><Input name="expires_at" type="date"/></Field></div><Field label="Notes" hint="Optional"><Textarea name="notes" rows={4} placeholder="What’s included, setup timing, delivery details, or anything your client should know."/></Field><FormError message={state.error}/><div className="flex justify-end"><Submit/></div></Card></form>;
}
